copy['pt'] = copy['pt_BR']
copy['zh'] = copy['zh_Hans']
for locale, text in copy.items():
    values = text.split('|')
    assert len(values) == len(keys), (locale, len(values), len(keys))
    path = Path(f'lib/l10n/app_{locale}.arb')
    # Append only new keys; preserve all existing translations and formatting.
    original = path.read_text(encoding='utf8')
    data = json.loads(original)
    additions = {}
    for key, value in zip(keys, values):
        assert key not in data, key
        additions[key] = value
        if locale == 'en':
            additions['@' + key] = {'description': 'Livestream destination, consent, transport status or encrypted local storage. Keep RTMP, RTMPS, H264 and URL intact. Linguistic review pending.'}
    body = json.dumps(additions, ensure_ascii=False, indent=2)[1:-1]
    path.write_text(original.rstrip()[:-1].rstrip() + ',' + body + '\n}\n', encoding='utf8')
path = Path('lib/l10n/message_catalog.dart')
text = path.read_text(encoding='utf8')
arms = ''.join(f'  {json.dumps(value, ensure_ascii=False)} => l10n.{key},\n' for key, value in zip(keys, copy['en'].split('|')))
text = text.replace(') => switch (source) {\n', ') => switch (source) {\n' + arms, 1)
path.write_text(text, encoding='utf8')
print(f'Added {len(keys)} live messages to {len(copy)} ARBs and existing message adapter; human review remains pending.')
